parameters.emailMessage/Cc:
@if(
  or(empty(triggerBody()?['support_cc']), equals(triggerBody()?['afsender_mail'], triggerBody()?['support_cc'])),
  triggerBody()?['afsender_mail'],
  concat(triggerBody()?['afsender_mail'], ';', triggerBody()?['support_cc'])
)

inputs.value:
@concat(
  items('Apply_to_each_2')?['beskrivelse'],
  '    Dag: ', string(items('Apply_to_each_2')?['rabat_dag_pct']), '%',
  if(
    greater(float(if(empty(string(items('Apply_to_each_2')?['rabat_maaned_pct'])),'0',string(items('Apply_to_each_2')?['rabat_maaned_pct']))),0),
    concat(' / Måned: ', string(items('Apply_to_each_2')?['rabat_maaned_pct']), '%'),
    ''
  ),
  decodeUriComponent('%0A')
)

